SELECT PetType, AVG(pet_age) AS average_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(pet_age) AS average_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(weight) AS avg_weight
FROM Pets
GROUP BY PetType;

SELECT DISTINCT s.Fname, s.Age
FROM Student s
JOIN Has_Pet hp ON s.StuID = hp.StuID;

SELECT StuID, COUNT(PetID) AS pet_count
FROM Has_Pet
GROUP BY StuID;

SELECT StuID, COUNT(PetID) AS pet_count
FROM Has_Pet
GROUP BY StuID;

SELECT Template_ID, COUNT(Document_ID) AS Number_of_Documents
FROM Documents
GROUP BY Template_ID;

SELECT Template_Type_Code, COUNT(*) AS Template_Count
FROM Templates
GROUP BY Template_Type_Code;

SELECT Template_Type_Code, COUNT(*) AS Template_Count
FROM Templates
GROUP BY Template_Type_Code;

SELECT country_code, COUNT(*) AS number_of_players
FROM players
GROUP BY country_code;

SELECT country_code, COUNT(*) AS player_count
FROM players
GROUP BY country_code;

SELECT ranking_date, SUM(tours) AS total_tours
FROM rankings
GROUP BY ranking_date;

SELECT DISTINCT c.course_name
FROM Courses c
JOIN Student_Enrolment_Courses sec ON c.course_id = sec.course_id;

SELECT DISTINCT c.course_name
FROM Courses c
JOIN Student_Enrolment_Courses sec ON c.course_id = sec.course_id;

SELECT s.first_name
FROM Students s
WHERE s.permanent_address_id <> s.current_address_id;

SELECT Language, COUNT(*) AS channel_count
FROM TV_Channel
GROUP BY Language
HAVING COUNT(*) = (
    SELECT MIN(cnt) FROM (
        SELECT COUNT(*) AS cnt
        FROM TV_Channel
        GROUP BY Language
    )
);

SELECT DISTINCT Region FROM country
JOIN countrylanguage ON country.Code = countrylanguage.CountryCode
WHERE Language IN ('Dutch', 'English');

SELECT conductor.Name, orchestra.Orchestra
FROM conductor
JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;

SELECT conductor.Name, orchestra.Orchestra
FROM conductor
JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;

SELECT student_id, COUNT(friend_id) AS num_friends
FROM Friend
GROUP BY student_id;

SELECT student_id, COUNT(*) AS like_count
FROM Likes
GROUP BY student_id;

SELECT student_id, COUNT(*) AS like_count
FROM Likes
GROUP BY student_id;

SELECT state FROM Owners
INTERSECT
SELECT state FROM Professionals;

SELECT professional_id, role_code, email_address
FROM Professionals
WHERE professional_id NOT IN (
    SELECT professional_id
    FROM Treatments
);

SELECT t.date_of_treatment, p.first_name
FROM Treatments t
JOIN Professionals p ON t.professional_id = p.professional_id;

SELECT t.date_of_treatment, p.first_name
FROM Treatments t
JOIN Professionals p ON t.professional_id = p.professional_id;

SELECT t.cost_of_treatment, tt.treatment_type_description
FROM Treatments t
JOIN Treatment_Types tt ON t.treatment_type_code = tt.treatment_type_code;

SELECT t.cost_of_treatment, tt.treatment_type_description
FROM Treatments t
JOIN Treatment_Types tt ON t.treatment_type_code = tt.treatment_type_code;

SELECT o.first_name, d.name
FROM Owners o
JOIN Dogs d ON o.owner_id = d.owner_id;

SELECT d.date_arrived, d.date_departed
FROM Dogs d
JOIN Treatments t ON d.dog_id = t.dog_id;

SELECT d.date_arrived, d.date_departed
FROM Dogs d
JOIN Treatments t ON d.dog_id = t.dog_id;

SELECT DISTINCT rpt.property_type_description
FROM Ref_Property_Types rpt
JOIN Properties p ON p.property_type_code = rpt.property_type_code;
